class Solution {
    public int maxProfit(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i - 1]) {
                profit += prices[i] - prices[i - 1];
            }
        }
        return profit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int profit = 0;
        int i = 0;
        while (i < prices.length - 1) {
            while (i < prices.length - 1 && prices[i] >= prices[i + 1]) {
                i++;
            }
            int valley = prices[i];
            while (i < prices.length - 1 && prices[i] <= prices[i + 1]) {
                i++;
            }
            int peak = prices[i];
            profit += peak - valley;
        }
        return profit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int cash = 0;
        int hold = -prices[0];
        for (int i = 1; i < prices.length; i++) {
            int prevCash = cash;
            cash = Math.max(cash, hold + prices[i]);
            hold = Math.max(hold, prevCash - prices[i]);
        }
        return cash;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[] cash = new int[n];
        int[] hold = new int[n];
        hold[0] = -prices[0];
        for (int i = 1; i < n; i++) {
            cash[i] = Math.max(cash[i - 1], hold[i - 1] + prices[i]);
            hold[i] = Math.max(hold[i - 1], cash[i - 1] - prices[i]);
        }
        return cash[n - 1];
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int profit = 0;
        int buy = prices[0];
        for (int i = 1; i <= prices.length; i++) {
            if (i == prices.length || prices[i] < prices[i - 1]) {
                profit += Math.max(0, prices[i - 1] - buy);
                if (i < prices.length) {
                    buy = prices[i];
                }
            }
        }
        return profit;
    }
}
